def sem(rs1, rs2, state):
    # rqsat: rd = clamp( round_shift_right( signed(rs1), rs2[4:0] ), -128, 127 ), tra ve dang mo rong dau 32 bit
    x = rs1 - (1 << 32) if (rs1 & 0x80000000) else rs1
    s = rs2 & 0x1F
    if state.get('funct7', 0) & 1:
        y = x >> s
    else:
        y = (x + (1 << (s - 1))) >> s if s > 0 else x
    if y > 127:
        y = 127
    elif y < -128:
        y = -128
    return y & 0xFFFFFFFF, state

def sem(rs1, rs2, state):
    # Mang MAC 4x4 trong kien truc: ACC[i][j] += A[i] * W[j] cho i,j in 0..3,
    # voi A, W la hai dem 4 phan tu int8 nap truoc tu DMEM.
    f3 = state.get('funct3', 0)
    acc = state.setdefault('ARR', [[0] * 4 for _ in range(4)])
    if f3 == 0:
        state['A'] = [((rs1 >> (8 * k)) & 0xFF) - 256 if ((rs1 >> (8 * k)) & 0x80) else ((rs1 >> (8 * k)) & 0xFF) for k in range(4)]
        return 0, state
    if f3 == 1:
        state['W'] = [((rs1 >> (8 * k)) & 0xFF) - 256 if ((rs1 >> (8 * k)) & 0x80) else ((rs1 >> (8 * k)) & 0xFF) for k in range(4)]
        return 0, state
    if f3 == 2:
        for i in range(4):
            for j in range(4):
                acc[i][j] = (acc[i][j] + state['A'][i] * state['W'][j]) & 0xFFFFFFFF
        return 0, state
    sel = state.get('funct7', 0) & 0x0F
    v = acc[sel >> 2][sel & 3]
    if state.get('funct7', 0) & 0x10:
        acc[sel >> 2][sel & 3] = 0
    return v & 0xFFFFFFFF, state
